import React, { useEffect, useState } from "react";

const ReceiptPage = () => {
  const [receipts, setReceipts] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch("http://localhost:5000/api/receipts") // backend route to fetch all receipts
      .then((res) => res.json())
      .then((data) => {
        setReceipts(data);
        setLoading(false);
      })
      .catch((err) => {
        console.error("Error fetching receipts:", err);
        setLoading(false);
      });
  }, []);

  if (loading) return <p className="text-center text-gray-500">Loading receipts...</p>;

  return (
    <div className="p-6 max-w-4xl mx-auto">
      <h1 className="text-2xl font-bold mb-6 text-center">All Receipts</h1>

      {receipts.length === 0 ? (
        <p className="text-center text-gray-500">No receipts found.</p>
      ) : (
        receipts.map((receipt) => (
          <div key={receipt._id} className="border rounded-lg shadow-md p-5 mb-6 bg-white">
            <h2 className="text-xl font-semibold mb-2">{receipt.name}</h2>
            <p className="text-gray-600 mb-1">
              <strong>Email:</strong> {receipt.email}
            </p>
            <p className="text-gray-600 mb-3">
              <strong>Date:</strong>{" "}
              {new Date(receipt.timestamp).toLocaleString()}
            </p>

            <table className="w-full border-collapse mb-3">
              <thead>
                <tr className="bg-gray-100">
                  <th className="border p-2 text-left">Product</th>
                  <th className="border p-2">Qty</th>
                  <th className="border p-2">Price</th>
                  <th className="border p-2">Subtotal</th>
                </tr>
              </thead>
              <tbody>
                {receipt.items.map((item, idx) => (
                  <tr key={idx}>
                    <td className="border p-2">{item.name}</td>
                    <td className="border p-2 text-center">{item.qty}</td>
                    <td className="border p-2 text-center">${item.price.toFixed(2)}</td>
                    <td className="border p-2 text-center">${item.subtotal.toFixed(2)}</td>
                  </tr>
                ))}
              </tbody>
            </table>

            <div className="text-right font-semibold">
              Total: <span className="text-green-600">${receipt.total.toFixed(2)}</span>
            </div>
          </div>
        ))
      )}
    </div>
  );
};

export default ReceiptPage;
